// Code node: "Parse Perplexity AI Response"
const input = $input.first().json;

// Извлекаем контент из структуры Perplexity API
let newsContent = '';

if (input.choices && input.choices[0] && input.choices[0].message) {
  newsContent = input.choices[0].message.content;
} else if (input.content) {
  newsContent = input.content;
} else if (typeof input === 'string') {
  newsContent = input;
}

try {
  // Парсим JSON из контента
  const newsArray = JSON.parse(newsContent);

  // Проверяем, что это массив
  if (Array.isArray(newsArray)) {
    // Преобразуем каждую новость в отдельный item для n8n
    const processedNews = newsArray.map((news, index) => ({
      json: {
        // Основные поля для видео генерации
        id: index + 1,
        title: news.title || 'AI News Update',
        description: news.description || news.video_description || '',
        source: news.source || 'AI News',
        date: news.date || new Date().toISOString().split('T')[0],

        // Дополнительные поля
        video_potential: news.video_potential || news.why_viral || '',
        tags: news.tags || ['ai', 'technology'],
        engagement_score: news.engagement_score || 5,
        target_audience: news.target_audience || 'general tech audience',

        // Для совместимости с существующим workflow
        content: news.description || news.video_description || '',
        link: `https://example.com/news/${index + 1}`, // Placeholder link
        guid: `ai-news-${Date.now()}-${index}`,
        pubDate: news.date || new Date().toISOString(),
        isoDate: news.date || new Date().toISOString(),

        // Метаданные Perplexity
        perplexity_citations: input.citations || [],
        perplexity_cost: input.usage?.total_cost || 0,
        ai_generated: true
      }
    }));

    console.log(`Успешно обработано ${processedNews.length} новостей из Perplexity AI`);
    return processedNews;

  } else {
    throw new Error('Ответ не является массивом новостей');
  }

} catch (error) {
  console.log('Ошибка парсинга JSON:', error.message);
  console.log('Сырой контент:', newsContent);

  // Fallback: создаем одну новость из всего текста
  return [{
    json: {
      id: 1,
      title: 'AI News Summary',
      description: newsContent.substring(0, 200) + '...',
      source: 'Perplexity AI',
      date: new Date().toISOString().split('T')[0],
      content: newsContent,
      link: 'https://perplexity.ai',
      guid: `ai-news-${Date.now()}`,
      pubDate: new Date().toISOString(),
      isoDate: new Date().toISOString(),
      tags: ['ai', 'news'],
      engagement_score: 5,
      ai_generated: true,
      error: 'JSON parsing failed, using raw content'
    }
  }];
}

// Code node: "Extract Video Script" (Updated for longer videos)
const items = $input.all();

// Извлекаем данные из результата AI Agent
const processedData = items.map((item) => {
  const output = item.json.output;

  return {
    // Основные поля для совместимости с оригинальным workflow
    title: output.viral_headline || 'AI News Update',
    content: output.video_script || '',

    // Дополнительные поля от AI Agent
    video_script: output.video_script,
    viral_headline: output.viral_headline,
    hook_opening: output.hook_opening,
    selected_news_id: output.selected_news_id,
    why_selected: output.why_selected,
    emotion_trigger: output.emotion_trigger,

    // ✅ НОВЫЕ ПОЛЯ для структурированного скрипта
    script_structure: output.script_structure || {
      hook: output.hook_opening || '',
      setup: '',
      main_story: output.video_script || '',
      impact: '',
      cta: ''
    },

    // Поля для совместимости с HeyGen workflow
    news_title: output.viral_headline,
    caption: output.video_script,

    // Метаданные
    source: 'AI Agent Generated',
    date: new Date().toISOString().split('T')[0],
    guid: `ai-viral-${Date.now()}`,
    pubDate: new Date().toISOString(),
    isoDate: new Date().toISOString(),
    link: 'https://ai-news-generated.com',

    // ✅ УЛУЧШЕННАЯ АНАЛИТИКА для длинных скриптов
    script_analytics: {
      total_length: output.video_script ? output.video_script.length : 0,
      word_count: output.video_script ? output.video_script.split(' ').length : 0,
      estimated_duration_sec: output.video_script ? Math.round(output.video_script.split(' ').length / 3) : 0,
      has_structure: output.script_structure ? true : false,
      structure_parts: output.script_structure ? Object.keys(output.script_structure).length : 0
    },

    // Обратная совместимость
    script_length: output.video_script ? output.video_script.length : 0,
    word_count: output.video_script ? output.video_script.split(' ').length : 0,
    ai_generated: true,

    // ✅ МЕТКИ ДЛЯ ДЛИННЫХ ВИДЕО
    video_type: 'long_form', // 30-40 seconds
    content_quality: 'structured',
    processing_timestamp: new Date().toISOString()
  };
});

// ✅ РАСШИРЕННОЕ ЛОГИРОВАНИЕ
console.log(`📊 === ОБРАБОТКА ВИДЕО СКРИПТА ===`);
console.log(`📝 Обработано скриптов: ${processedData.length}`);

if (processedData.length > 0) {
  const data = processedData[0];
  console.log(`📰 Заголовок: "${data.viral_headline}"`);
  console.log(`📊 Длина скрипта: ${data.script_analytics.total_length} символов`);
  console.log(`🔢 Количество слов: ${data.script_analytics.word_count}`);
  console.log(`⏱️ Примерная длительность: ${data.script_analytics.estimated_duration_sec} секунд`);
  console.log(`🏗️ Структурированный: ${data.script_analytics.has_structure ? 'Да' : 'Нет'}`);

  if (data.script_structure) {
    console.log(`📋 Структура скрипта:`);
    console.log(`   🎯 Hook: "${data.script_structure.hook?.substring(0, 50)}..."`);
    console.log(`   📖 Setup: "${data.script_structure.setup?.substring(0, 50)}..."`);
    console.log(`   📰 Main: "${data.script_structure.main_story?.substring(0, 50)}..."`);
    console.log(`   💥 Impact: "${data.script_structure.impact?.substring(0, 50)}..."`);
    console.log(`   🎬 CTA: "${data.script_structure.cta?.substring(0, 50)}..."`);
  }

  // ✅ ПРОВЕРКА КАЧЕСТВА СКРИПТА
  const quality_checks = {
    adequate_length: data.script_analytics.word_count >= 80 && data.script_analytics.word_count <= 120,
    good_duration: data.script_analytics.estimated_duration_sec >= 25 && data.script_analytics.estimated_duration_sec <= 45,
    has_hook: data.hook_opening && data.hook_opening.length > 10,
    has_structure: data.script_analytics.has_structure
  };

  const quality_score = Object.values(quality_checks).filter(Boolean).length;
  console.log(`✅ Оценка качества: ${quality_score}/4`);

  if (quality_score < 3) {
    console.log(`⚠️ ВНИМАНИЕ: Низкое качество скрипта. Возможные проблемы:`);
    if (!quality_checks.adequate_length) console.log(`   - Неподходящая длина: ${data.script_analytics.word_count} слов (нужно 80-120)`);
    if (!quality_checks.good_duration) console.log(`   - Неподходящая длительность: ${data.script_analytics.estimated_duration_sec} сек (нужно 25-45)`);
    if (!quality_checks.has_hook) console.log(`   - Слабый hook: ${data.hook_opening?.length || 0} символов`);
    if (!quality_checks.has_structure) console.log(`   - Отсутствует структура скрипта`);
  } else {
    console.log(`🎉 Скрипт готов к генерации видео!`);
  }
}

// Возвращаем в формате, совместимом с оригинальным workflow
return processedData.map(item => ({ json: item }));

