// Code node: "Smart Random News Selector"
const items = $input.all();

if (!items || items.length === 0) {
  throw new Error('❌ Нет новостей для выбора');
}

console.log(`📰 Получено ${items.length} новостей для случайного выбора`);

// 🎯 СТРАТЕГИИ ВЫБОРА

// Стратегия 1: Полностью случайный выбор
function randomSelection(newsArray) {
  const randomIndex = Math.floor(Math.random() * newsArray.length);
  console.log(`🎲 Случайный выбор: индекс ${randomIndex + 1} из ${newsArray.length}`);
  return newsArray[randomIndex];
}

// Стратегия 2: Взвешенный случайный выбор по engagement_score
function weightedRandomSelection(newsArray) {
  // Создаем веса на основе engagement_score
  const weights = newsArray.map(item => {
    const score = parseInt(item.json.engagement_score) || 5;
    return Math.max(score, 1); // Минимальный вес = 1
  });

  const totalWeight = weights.reduce((sum, weight) => sum + weight, 0);
  const random = Math.random() * totalWeight;

  let currentWeight = 0;
  for (let i = 0; i < newsArray.length; i++) {
    currentWeight += weights[i];
    if (random <= currentWeight) {
      console.log(`⚖️ Взвешенный выбор: ID ${newsArray[i].json.id} (score: ${newsArray[i].json.engagement_score})`);
      return newsArray[i];
    }
  }

  return newsArray[0]; // Fallback
}

// Стратегия 3: Умный выбор с фильтрацией по качеству
function smartRandomSelection(newsArray) {
  // Фильтруем по качественным критериям
  const qualityNews = newsArray.filter(item => {
    const score = parseInt(item.json.engagement_score) || 0;
    const hasGoodTitle = item.json.title && item.json.title.length > 20;
    const hasContent = item.json.description && item.json.description.length > 50;
    const hasVideoContent = item.json.video_potential && item.json.video_potential.length > 30;

    return score >= 7 && hasGoodTitle && hasContent && hasVideoContent;
  });

  // Если есть качественные новости - выбираем из них, иначе из всех
  const sourceArray = qualityNews.length > 0 ? qualityNews : newsArray;

  console.log(`🎯 Умный выбор: ${qualityNews.length} качественных из ${newsArray.length} общих`);

  // Взвешенный выбор из отфильтрованных
  return weightedRandomSelection(sourceArray);
}

// 🎲 ВЫБОР СТРАТЕГИИ (можете изменить здесь)
const strategy = 'smart'; // 'random', 'weighted', 'smart'

let selectedNews;
switch(strategy) {
  case 'weighted':
    selectedNews = weightedRandomSelection(items);
    break;
  case 'smart':
    selectedNews = smartRandomSelection(items);
    break;
  default:
    selectedNews = randomSelection(items);
}

// 📊 Детальное логирование выбора
const selectedIndex = items.findIndex(item => item.json.id === selectedNews.json.id);
console.log(`\n🎯 === РЕЗУЛЬТАТ ВЫБОРА ===`);
console.log(`📋 Выбрана новость ID: ${selectedNews.json.id}`);
console.log(`📰 Заголовок: "${selectedNews.json.title}"`);
console.log(`📈 Engagement score: ${selectedNews.json.engagement_score}/10`);
console.log(`🎲 Стратегия: ${strategy}`);
console.log(`📍 Позиция: ${selectedIndex + 1}/${items.length}`);
console.log(`📅 Дата: ${selectedNews.json.date}`);
console.log(`🎬 Video potential: ${selectedNews.json.video_potential ? 'есть' : 'нет'}`);

// 🏷️ Добавляем метаданные о выборе
const enrichedNews = {
  ...selectedNews.json,

  // Метаданные процесса выбора
  selection_metadata: {
    strategy: strategy,
    selected_from_total: items.length,
    selection_timestamp: new Date().toISOString(),
    random_seed: Math.random().toString(36).substring(7),
    original_position: selectedIndex + 1,
    selection_reason: strategy === 'smart' ? 'quality_filtered' : 
                     strategy === 'weighted' ? 'engagement_weighted' : 'pure_random'
  },

  // Статистика по всем новостям для аналитики
  batch_statistics: {
    all_scores: items.map(item => parseInt(item.json.engagement_score) || 0),
    average_score: items.reduce((sum, item) => sum + (parseInt(item.json.engagement_score) || 0), 0) / items.length,
    max_score: Math.max(...items.map(item => parseInt(item.json.engagement_score) || 0)),
    total_news_count: items.length,
    sources: items.map(item => item.json.source).filter((v, i, a) => a.indexOf(v) === i)
  },

  // Флаги для следующих нод
  ready_for_video: true,
  processing_stage: 'selected_for_video_generation',
  workflow_timestamp: new Date().toISOString()
};

// 🎉 Финальный вывод
console.log(`\n✅ Новость успешно выбрана и готова для создания видео!`);
console.log(`🔄 Средний engagement score батча: ${enrichedNews.batch_statistics.average_score.toFixed(1)}`);

// Возвращаем ТОЛЬКО выбранную новость
return [{ json: enrichedNews }];
